export function clamp(x, lo, hi) {
  if (lo > hi) throw new RangeError(`clamp: lo (${lo}) > hi (${hi})`);
  return Math.min(Math.max(x, lo), hi);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/clamp.mjs";

test("clamp limits values to [lo, hi]", () => {
  assert.equal(clamp(-1, 0, 10), 0);
  assert.equal(clamp(7, 0, 10), 7);
  assert.equal(clamp(11, 0, 10), 10);
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});

test("clamp with equal bounds returns that bound", () => {
  assert.equal(clamp(-5, 3, 3), 3);
  assert.equal(clamp(9, 3, 3), 3);
});

test("clamp throws RangeError on reversed bounds", () => {
  assert.throws(() => clamp(0, 10, 0), RangeError);
});
